		if TsIsUndefined(value) {
			return fallback
		}
		if !TsIsNumeric(value) {
			TsFSInvalid(name, "a number")
		}
		n := TsNumber(value)
		if math.IsNaN(n) || math.IsInf(n, 0) || math.Trunc(n) != n || n < 0 || n > 4294967296 {
			panic(TsThrown{TsFSException("RangeError", "ERR_OUT_OF_RANGE", name+" is out of range")})
		}
