func TsNodeVMContextOptions(loop *TsLoop, options TsValue) *TsNodeVMContextState {
	state := &TsNodeVMContextState{AllowStrings: true, AllowWasm: true, Importer: TsU}
	if TsIsUndefined(options) {
		return state
	}
	opts := TsNodeVMOptions(options)
	for _, field := range []string{"name", "origin"} {
		value := TsGet(loop, opts, TsStringReference(TsStringUTF8(field)))
		if !TsIsUndefined(value) && value.Kind != TsStringKind {
			TsFSInvalid("options."+field, "a string")
		}
		if value.Kind == TsStringKind {
			if field == "name" {
				state.Name = TsText(value)
			} else {
				state.Origin = TsText(value)
			}
		}
	}
	microtask := TsGet(loop, opts, TsStringReference(TsStringUTF8("microtaskMode")))
	if !TsIsUndefined(microtask) {
		if microtask.Kind != TsStringKind || TsText(microtask) != "afterEvaluate" {
			panic(TsThrown{TsFSException("TypeError", "ERR_INVALID_ARG_VALUE", "The value of \"options.microtaskMode\" is invalid")})
		}
		state.MicrotaskMode = "afterEvaluate"
	}
	codeGeneration := TsGet(loop, opts, TsStringReference(TsStringUTF8("codeGeneration")))
	if !TsIsUndefined(codeGeneration) {
		if codeGeneration.Kind != TsObjectKind && codeGeneration.Kind != TsInstanceKind {
			TsFSInvalid("options.codeGeneration", "an object")
		}
		for _, field := range []string{"strings", "wasm"} {
			value := TsGet(loop, codeGeneration, TsStringReference(TsStringUTF8(field)))
			if TsIsUndefined(value) {
				continue
			}
			if value.Kind != TsBooleanKind {
				TsFSInvalid("options.codeGeneration."+field, "a boolean")
			}
			if field == "strings" {
				state.AllowStrings = TsTruthy(value)
			} else {
				state.AllowWasm = TsTruthy(value)
			}
		}
	}
	importer := TsGet(loop, opts, TsStringReference(TsStringUTF8("importModuleDynamically")))
	if importer.Kind == TsFunctionKind {
		state.Importer = importer
	}
	return state
}
func TsNodeVMCreateContext(loop *TsLoop, context, options TsValue) TsValue {
	state := TsNodeVMContextOptions(loop, options)
	if TsIsUndefined(context) {
		context = TsObjectValue(TsNewObject())
	} else if context.Kind == TsSymbolKind {
		dont := TsGet(loop, TsNodeVMSingleton.Constants, TsStringReference(TsStringUTF8("DONT_CONTEXTIFY")))
		if !TsStrictEqual(context, dont) {
			TsFSInvalid("contextObject", "an object")
		}
		state.NotContextified = true
		context = TsObjectValue(TsNewObject())
	} else if context.Kind != TsObjectKind && context.Kind != TsInstanceKind {
		TsFSInvalid("contextObject", "an object")
	}
	key := uintptr(context.Ref)
	if TsNodeVMSingleton.Contexts[key] {
		return context
	}
	state.Object = context
	TsNodeVMSingleton.Contexts[key] = true
	TsNodeVMSingleton.ContextOptions[key] = state
	globalThis := TsStringReference(TsStringUTF8("globalThis"))
	if TsIsUndefined(TsNodeVMKey(loop, context, globalThis)) {
		TsNodeVMSet(loop, context, globalThis, context)
	}
	return context
}
func TsNodeVMScriptState(value TsValue) TsValue {
	if value.Kind != TsObjectKind {
		return TsU
	}
	return TsNodeVMSingleton.Scripts[uintptr(value.Ref)]
}
func TsNodeVMSourceMapURL(source string) TsValue {
	for _, marker := range []string{"//# sourceMappingURL=", "//@ sourceMappingURL="} {
		if index := strings.LastIndex(source, marker); index >= 0 {
			line := source[index+len(marker):]
			if newline := strings.IndexAny(line, "\r\n"); newline >= 0 {
				line = line[:newline]
			}
			line = strings.TrimSpace(line)
			if line != "" {
				return TsStringReference(TsStringUTF8(line))
			}
		}
	}
	return TsU
}
func TsNodeVMPrepareScriptOptions(loop *TsLoop, value TsValue, allowFilenameString bool) TsValue {
	if allowFilenameString && value.Kind == TsStringKind {
		options := TsNewObject()
		options.Set("filename", value)
		return TsObjectValue(options)
	}
	opts := TsNodeVMOptions(value)
	for _, name := range []string{"filename", "contextName", "contextOrigin"} {
		field := TsGet(loop, opts, TsStringReference(TsStringUTF8(name)))
		if !TsIsUndefined(field) && field.Kind != TsStringKind {
			TsFSInvalid("options."+name, "a string")
		}
	}
	for _, name := range []string{"lineOffset", "columnOffset"} {
		field := TsGet(loop, opts, TsStringReference(TsStringUTF8(name)))
		if !TsIsUndefined(field) && (!TsIsNumeric(field) || math.Trunc(TsNumber(field)) != TsNumber(field) || TsNumber(field) < math.MinInt32 || TsNumber(field) > math.MaxInt32) {
			TsFSInvalid("options."+name, "an integer")
		}
	}
	produce := TsGet(loop, opts, TsStringReference(TsStringUTF8("produceCachedData")))
	if !TsIsUndefined(produce) && produce.Kind != TsBooleanKind {
		TsFSInvalid("options.produceCachedData", "a boolean")
	}
	if cached := TsGet(loop, opts, TsStringReference(TsStringUTF8("cachedData"))); !TsIsUndefined(cached) && cached.Kind != TsTypedArrayKind && cached.Kind != TsDataViewKind {
		TsFSInvalid("options.cachedData", "Buffer, TypedArray, or DataView")
	}
	if timeout := TsGet(loop, opts, TsStringReference(TsStringUTF8("timeout"))); !TsIsUndefined(timeout) && (!TsIsNumeric(timeout) || math.Trunc(TsNumber(timeout)) != TsNumber(timeout) || TsNumber(timeout) < 1) {
		TsFSInvalid("options.timeout", "an integer greater than or equal to 1")
	}
	return opts
}
func TsNodeVMNewScript(loop *TsLoop, source, options TsValue) TsValue {
	if TsIsUndefined(source) {
		source = TsStringReference(TsStringUTF8(""))
	} else if source.Kind != TsStringKind {
		source = TsStringReference(TsStringUTF8(TsText(source)))
	}
	_ = TsNodeVMPrepareScriptOptions(loop, options, true)
	TsRuntimeUnsupported("node:vm Script compilation", "the Go program is statically compiled and cannot compile JavaScript source strings")
	return TsU
}
func TsNodeVMRunOptions(loop *TsLoop, value TsValue) TsValue {
	opts := TsNodeVMOptions(value)
	filename := TsGet(loop, opts, TsStringReference(TsStringUTF8("filename")))
	if !TsIsUndefined(filename) && filename.Kind != TsStringKind {
		TsFSInvalid("options.filename", "a string")
	}
	for _, name := range []string{"lineOffset", "columnOffset"} {
		field := TsGet(loop, opts, TsStringReference(TsStringUTF8(name)))
		if !TsIsUndefined(field) && (!TsIsNumeric(field) || math.Trunc(TsNumber(field)) != TsNumber(field) || TsNumber(field) < math.MinInt32 || TsNumber(field) > math.MaxInt32) {
			TsFSInvalid("options."+name, "an integer")
		}
	}
	for _, name := range []string{"displayErrors", "breakOnSigint"} {
		field := TsGet(loop, opts, TsStringReference(TsStringUTF8(name)))
		if !TsIsUndefined(field) && field.Kind != TsBooleanKind {
			TsFSInvalid("options."+name, "a boolean")
		}
	}
	if timeout := TsGet(loop, opts, TsStringReference(TsStringUTF8("timeout"))); !TsIsUndefined(timeout) && (!TsIsNumeric(timeout) || math.Trunc(TsNumber(timeout)) != TsNumber(timeout) || TsNumber(timeout) < 1) {
		TsFSInvalid("options.timeout", "an integer greater than or equal to 1")
	}
	return opts
}
