func TsNodeVMRunObjectOptions(loop *TsLoop, value TsValue) TsValue {
	if value.Kind == TsStringKind {
		opts := TsNewObject()
		opts.Set("filename", value)
		return TsObjectValue(opts)
	}
	if TsNullish(value) || value.Kind != TsObjectKind && value.Kind != TsInstanceKind {
		return TsObjectValue(TsNewObject())
	}
	return TsObjectValue(TsNodeTLSObjectCopy(value))
}

type TsNodeVMLexeme struct {
	Text string
	Kind byte
	Line int
}
type TsNodeVMRequest struct {
	Specifier      string
	Attributes     map[string]string
	AttributeOrder []string
}

func TsNodeVMIdentifierByte(value byte) bool {
	return value == '_' || value == '$' || value >= 'a' && value <= 'z' || value >= 'A' && value <= 'Z' || value >= '0' && value <= '9' || value >= 0x80
}
func TsNodeVMDecodeString(raw string, quote byte) string {
	if quote == '"' {
		if value, err := strconv.Unquote("\"" + raw + "\""); err == nil {
			return value
		}
	}
	return strings.NewReplacer("\\n", "\n", "\\r", "\r", "\\t", "\t", "\\'", "'", "\\\"", "\"", "\\\\", "\\").Replace(raw)
}
func TsNodeVMLex(source string) []TsNodeVMLexeme {
	tokens := []TsNodeVMLexeme{}
	line := 1
	for index := 0; index < len(source); {
		current := source[index]
		if current == ' ' || current == '\t' || current == '\r' || current == '\n' {
			if current == '\n' {
				line++
			}
			index++
			continue
		}
		if current == '/' && index+1 < len(source) && source[index+1] == '/' {
			index += 2
			for index < len(source) && source[index] != '\n' {
				index++
			}
			continue
		}
		if current == '/' && index+1 < len(source) && source[index+1] == '*' {
			index += 2
			for index+1 < len(source) && !(source[index] == '*' && source[index+1] == '/') {
				if source[index] == '\n' {
					line++
				}
				index++
			}
			if index+1 < len(source) {
				index += 2
			}
			continue
		}
		start := index
		tokenLine := line
		if current == '\'' || current == '"' || current == 0x60 {
			quote := current
			index++
			for index < len(source) {
				if source[index] == '\\' {
					index += 2
					continue
				}
				if source[index] == quote {
					break
				}
				if source[index] == '\n' {
					line++
				}
				index++
			}
			end := index
			if index < len(source) {
				index++
			}
			tokens = append(tokens, TsNodeVMLexeme{Text: TsNodeVMDecodeString(source[start+1:end], quote), Kind: 's', Line: tokenLine})
			continue
		}
		if TsNodeVMIdentifierByte(current) {
			index++
			for index < len(source) && TsNodeVMIdentifierByte(source[index]) {
				index++
			}
			tokens = append(tokens, TsNodeVMLexeme{Text: source[start:index], Kind: 'i', Line: tokenLine})
			continue
		}
		index++
		tokens = append(tokens, TsNodeVMLexeme{Text: source[start:index], Kind: 'p', Line: tokenLine})
	}
	return tokens
}
func TsNodeVMStaticRequests(source string) []TsNodeVMRequest {
	tokens := TsNodeVMLex(source)
	requests := []TsNodeVMRequest{}
	depth := 0
	for index := 0; index < len(tokens); index++ {
		token := tokens[index]
		if depth == 0 && (token.Text == "import" || token.Text == "export") {
			if token.Text == "import" && index+1 < len(tokens) && tokens[index+1].Kind == 's' {
				requests = append(requests, TsNodeVMRequest{Specifier: tokens[index+1].Text, Attributes: map[string]string{}})
				index++
				continue
			}
			if token.Text == "import" && index+1 < len(tokens) && (tokens[index+1].Text == "(" || tokens[index+1].Text == "." || tokens[index+1].Text == "=") {
				continue
			}
			line := token.Line
			from := -1
			for cursor := index + 1; cursor < len(tokens); cursor++ {
				if tokens[cursor].Text == ";" || (tokens[cursor].Line > line && (tokens[cursor].Text == "import" || tokens[cursor].Text == "export")) {
					break
				}
				if tokens[cursor].Text == "from" && cursor+1 < len(tokens) && tokens[cursor+1].Kind == 's' {
					from = cursor
					break
				}
			}
			if from >= 0 {
				request := TsNodeVMRequest{Specifier: tokens[from+1].Text, Attributes: map[string]string{}}
				cursor := from + 2
				if cursor+1 < len(tokens) && (tokens[cursor].Text == "with" || tokens[cursor].Text == "assert") && tokens[cursor+1].Text == "{" {
					for cursor += 2; cursor < len(tokens) && tokens[cursor].Text != "}"; {
						key := tokens[cursor].Text
						cursor++
						if cursor < len(tokens) && tokens[cursor].Text == ":" {
							cursor++
							if cursor < len(tokens) {
								if _, exists := request.Attributes[key]; !exists {
									request.AttributeOrder = append(request.AttributeOrder, key)
								}
								request.Attributes[key] = tokens[cursor].Text
								cursor++
							}
						}
						for cursor < len(tokens) && tokens[cursor].Text != "," && tokens[cursor].Text != "}" {
							cursor++
						}
						if cursor < len(tokens) && tokens[cursor].Text == "," {
							cursor++
						}
					}
				}
				requests = append(requests, request)
				index = from + 1
			}
		}
		switch token.Text {
		case "{", "(", "[":
			depth++
		case "}", ")", "]":
			if depth > 0 {
				depth--
			}
		}
	}
	return requests
}
