		event.Set("pid", TsInternalTraceGet(loop, process, "pid"))
		event.Set("tid", TsNumberValue(float64(TsInternalTraceEvents.Tid)))
		event.Set("ts", TsNumberValue(math.Round(TsInternalSharedPerformanceNow(loop)*1000)))
		event.Set("ph", TsInternalTraceKey("I"))
		event.Set("cat", TsInternalTraceKey("v8"))
		event.Set("name", TsInternalTraceKey("V8.GCScavenger"))
		event.Set("args", TsObjectValue(TsNewObject()))
