	json := TsGet(loop, TsGlobalObject(loop), TsInternalTraceKey("JSON"))
	serialized := TsCallReceiver(loop, TsInternalTraceGet(loop, json, "stringify"), json, payload)
	fs := TsFSModule(loop, "fs")
	write := TsInternalTraceGet(loop, fs, "writeFileSync")
