		if !strings.HasPrefix(name, prefix) || !strings.HasSuffix(name, ".part") {
			continue
		}
		part := TsCallReceiver(loop, TsInternalTraceGet(loop, path, "join"), path, dir, entry)
		var parsed TsValue
