func TsNodeURLParsePairs(query string) [][2]string {
	pairs := [][2]string{}
	query = strings.TrimPrefix(query, "?")
	if query == "" {
		return pairs
	}
	for _, part := range strings.Split(query, "&") {
		if part == "" {
			continue
		}
		key, value, has := strings.Cut(part, "=")
		if !has {
			value = ""
		}
		k, err := url.QueryUnescape(key)
		if err != nil {
			k = key
		}
		v, err := url.QueryUnescape(value)
		if err != nil {
			v = value
		}
		pairs = append(pairs, [2]string{k, v})
	}
	return pairs
}
func TsNodeURLFormEscape(value string) string {
	escaped := url.QueryEscape(value)
	return strings.ReplaceAll(escaped, "%2A", "*")
}
func TsNodeURLParamsString(state *TsNodeURLSearchParamsState) string {
	parts := make([]string, 0, len(state.Pairs))
	for _, pair := range state.Pairs {
		parts = append(parts, TsNodeURLFormEscape(pair[0])+"="+TsNodeURLFormEscape(pair[1]))
	}
	return strings.Join(parts, "&")
}
