	host := TsText(get("host"))
	if host == "null" || host == "" {
		host = TsText(get("hostname"))
		if host == "null" {
			host = ""
		}
		if strings.Contains(host, ":") && !strings.HasPrefix(host, "[") {
			host = "[" + host + "]"
		}
		port := TsText(get("port"))
		if port != "null" && port != "" {
			host += ":" + port
		}
	}
	pathname := TsText(get("pathname"))
