func TsNodeUtilBindingParseEnv(loop *TsLoop, value TsValue) TsValue {
	if value.Kind != TsStringKind {
		TsInternalValidatorInvalidType("content", "a string", value)
	}
	text := strings.TrimPrefix(TsText(value), "\ufeff")
	out := TsNewObject()
	for _, rawLine := range strings.Split(text, "\n") {
		line := strings.TrimSpace(strings.TrimSuffix(rawLine, "\r"))
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "export ") {
			line = strings.TrimSpace(strings.TrimPrefix(line, "export "))
		}
		split := strings.IndexByte(line, '=')
		if split < 0 {
			continue
		}
		key := strings.TrimSpace(line[:split])
		if key == "" {
			continue
		}
		valid := true
		for index, char := range key {
			if !(char == '_' || char >= 'A' && char <= 'Z' || char >= 'a' && char <= 'z' || index > 0 && char >= '0' && char <= '9') {
				valid = false
				break
			}
		}
		if !valid {
			continue
		}
		raw := strings.TrimSpace(line[split+1:])
		valueText := raw
		if len(raw) > 0 && (raw[0] == '\'' || raw[0] == '"' || raw[0] == 96) {
			quote := raw[0]
			end := strings.LastIndexByte(raw[1:], quote)
			if end >= 0 {
				valueText = raw[1 : 1+end]
				if quote == '"' {
					valueText = strings.NewReplacer("\\n", "\n", "\\r", "\r", "\\t", "\t", "\\\"", "\"", "\\\\", "\\").Replace(valueText)
				}
			} else {
				valueText = raw[1:]
			}
		} else {
			if comment := strings.Index(raw, " #"); comment >= 0 {
				raw = raw[:comment]
			}
			valueText = strings.TrimSpace(raw)
		}
		out.Set(key, TsStringReference(TsStringUTF8(valueText)))
	}
	return TsObjectValue(out)
}
