func TsInternalReplAcornModule(loop *TsLoop) TsValue {
	TsInternalReplAcorn.Do(func() {
		TsInternalReplAcorn.Module = TsInternalReplEvaluateBundle(loop, TsInternalReplAcornBundle, "acorn.js")
	})
	return TsInternalReplAcorn.Module
}

