func TsNodeSourceMapDecodeVLQ(text string) ([]int, bool) {
	alphabet := "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	values := []int{}
	for index := 0; index < len(text); {
		value := int64(0)
		shift := uint(0)
		for {
			if index >= len(text) || shift > 60 {
				return nil, false
			}
			digit := strings.IndexByte(alphabet, text[index])
			if digit < 0 {
				return nil, false
			}
			index++
			continuation := digit&32 != 0
			value |= int64(digit&31) << shift
			shift += 5
			if !continuation {
				break
			}
		}
		negative := value&1 != 0
		value >>= 1
		if negative {
			value = -value
		}
		values = append(values, int(value))
	}
	return values, true
}
