func TsNodeInspectGroupDigits(value string) string {
	sign := ""
	if strings.HasPrefix(value, "-") {
		sign = "-"
		value = value[1:]
	} else if strings.HasPrefix(value, "+") {
		sign = "+"
		value = value[1:]
	}
	if len(value) <= 3 {
		return sign + value
	}
	first := len(value) % 3
	if first == 0 {
		first = 3
	}
	parts := []string{value[:first]}
	for i := first; i < len(value); i += 3 {
		parts = append(parts, value[i:i+3])
	}
	return sign + strings.Join(parts, "_")
}
func TsNodeInspectNumberText(number float64, numericSeparator bool) string {
	value := TsNumberText(number)
	if !numericSeparator || math.IsNaN(number) || math.IsInf(number, 0) {
		return value
	}
	if dot := strings.IndexByte(value, '.'); dot >= 0 {
		return TsNodeInspectGroupDigits(value[:dot]) + "." + TsNodeInspectGroupDigits(value[dot+1:])
	}
	if exp := strings.IndexAny(value, "eE"); exp >= 0 {
		return TsNodeInspectGroupDigits(value[:exp]) + value[exp:]
	}
	return TsNodeInspectGroupDigits(value)
}
func TsNodeInspectBigIntText(value *big.Int, numericSeparator bool) string {
	text := value.String()
	if numericSeparator {
		text = TsNodeInspectGroupDigits(text)
	}
	return text + "n"
}
func TsNodeInspectContainer(parts []string, open, close string, depth int, o TsNodeInspectOptions) string {
	if len(parts) == 0 {
		return open + close
	}
	joined := strings.Join(parts, ", ")
	indent := strings.Repeat(" ", (depth+1)*2)
	closingIndent := strings.Repeat(" ", depth*2)
	if !strings.Contains(joined, "\n") && len(open)+len(joined)+len(close)+depth*2+2 <= o.BreakLength {
		return open + " " + joined + " " + close
	}
	return open + "\n" + indent + strings.Join(parts, ",\n"+indent) + "\n" + closingIndent + close
}
