	if TsInternalInspectState.Active[value.Ref] {
		TsInternalInspectState.ActiveMu.Unlock()
		return "", false
	}
	if TsInternalInspectState.Active == nil {
		TsInternalInspectState.Active = map[unsafe.Pointer]bool{}
	}
	TsInternalInspectState.Active[value.Ref] = true
	TsInternalInspectState.ActiveMu.Unlock()
