func TsNodeUtilDebugMatches(pattern, set string) bool {
	set = strings.ToUpper(set)
	for _, part := range strings.Split(strings.ToUpper(pattern), ",") {
		if part == "" {
			continue
		}
		p, s := 0, 0
		star, mark := -1, 0
		for s < len(set) {
			if p < len(part) && (part[p] == set[s] || part[p] == '?') {
				p++
				s++
				continue
			}
			if p < len(part) && part[p] == '*' {
				star = p
				p++
				mark = s
				continue
			}
			if star >= 0 {
				p = star + 1
				mark++
				s = mark
				continue
			}
			break
		}
		for p < len(part) && part[p] == '*' {
			p++
		}
		if p == len(part) && s == len(set) {
			return true
		}
	}
	return false
}

