func TsInternalSharedConstructors(loop *TsLoop, module *TsObject) {
	hostPort := TsInternalSharedErrorClass("ExceptionWithHostPort", 5, func(loop *TsLoop, args []TsValue, prototype TsValue) TsValue {
		errno, syscall, address, port, additional := TsArg(args, 0), TsArg(args, 1), TsArg(args, 2), TsArg(args, 3), TsArg(args, 4)
		code := TsInternalSharedSystemErrorName(loop, errno)
		details := ""
		if TsTruthy(port) && TsNumber(port) > 0 {
			details = " " + TsText(address) + ":" + TsText(port)
		} else if TsTruthy(address) {
			details = " " + TsText(address)
		}
		if TsTruthy(additional) {
			details += " - Local (" + TsText(additional) + ")"
		}
		value := TsInternalSharedErrorValue(loop, TsStringReference(TsStringUTF8(TsText(syscall)+" "+TsText(code)+details)), prototype)
		object := (*TsObject)(value.Ref)
		object.Set("errno", errno)
		object.Set("code", code)
		object.Set("syscall", syscall)
		object.Set("address", address)
		if TsTruthy(port) {
			object.Set("port", port)
		}
		return value
	})
	errnoException := TsInternalSharedErrorClass("ErrnoException", 3, func(loop *TsLoop, args []TsValue, prototype TsValue) TsValue {
		errno, syscall, original := TsArg(args, 0), TsArg(args, 1), TsArg(args, 2)
		code := TsInternalSharedSystemErrorName(loop, errno)
		message := TsText(syscall) + " " + TsText(code)
		if TsTruthy(original) {
			message += " " + TsText(original)
		}
		value := TsInternalSharedErrorValue(loop, TsStringReference(TsStringUTF8(message)), prototype)
		object := (*TsObject)(value.Ref)
		object.Set("errno", errno)
		object.Set("code", code)
		object.Set("syscall", syscall)
		return value
	})
	connReset := TsInternalSharedErrorClass("ConnResetException", 1, func(loop *TsLoop, args []TsValue, prototype TsValue) TsValue {
		value := TsInternalSharedErrorValue(loop, TsArg(args, 0), prototype)
		(*TsObject)(value.Ref).Set("code", TsStringReference(TsStringUTF8("ECONNRESET")))
		return value
	})
	aggregate := TsInternalSharedErrorClass("NodeAggregateError", 2, func(loop *TsLoop, args []TsValue, prototype TsValue) TsValue {
		value := TsNewError(loop, "AggregateError", args)
		object := (*TsObject)(value.Ref)
		object.Prototype = prototype
		errorCode := TsU
		errors := TsArg(args, 0)
		if errors.Kind == TsArrayKind && (*TsArray)(errors.Ref).Length() > 0 {
			errorCode = TsGet(loop, (*TsArray)(errors.Ref).At(0), TsStringReference(TsStringUTF8("code")))
		}
		object.Set("code", errorCode)
		return value
	})
	module.Set("ExceptionWithHostPort", hostPort)
	module.Set("ErrnoException", errnoException)
	module.Set("ConnResetException", connReset)
	module.Set("NodeAggregateError", aggregate)
	errorConstructor := TsErrorConstructor("Error")
	aggregateConstructor := TsErrorConstructor("AggregateError")
	for _, item := range []struct{ Constructor, Returns TsValue }{{hostPort, errorConstructor}, {errnoException, errorConstructor}, {connReset, errorConstructor}, {aggregate, aggregateConstructor}} {
		prototype := TsGet(loop, item.Constructor, TsStringReference(TsStringUTF8("prototype")))
		TsSet(loop, prototype, TsStringReference(TsStringUTF8("constructor")), item.Returns)
	}
}

