func TsNodeNetAddress(addr net.Addr) (string, int, string) {
	if addr == nil {
		return "", 0, ""
	}
	switch value := addr.(type) {
	case *net.TCPAddr:
		family := "IPv6"
		if value.IP.To4() != nil {
			family = "IPv4"
		}
		return value.IP.String(), value.Port, family
	case *net.UDPAddr:
		family := "IPv6"
		if value.IP.To4() != nil {
			family = "IPv4"
		}
		return value.IP.String(), value.Port, family
	case *net.UnixAddr:
		return value.Name, 0, "Unix"
	default:
		host, portText, err := net.SplitHostPort(addr.String())
		if err == nil {
			port, _ := strconv.Atoi(portText)
			family := "IPv6"
			if ip := net.ParseIP(host); ip == nil || ip.To4() != nil {
				family = "IPv4"
			}
			return host, port, family
		}
		return addr.String(), 0, "Unix"
	}
}
