func TsNodeNetFormatListenError(loop *TsLoop, failure TsValue, address string, port int) TsValue {
	code := TsText(TsNodeNetGet(loop, failure, "code"))
	description := ""
	switch code {
	case "EADDRINUSE":
		description = "address already in use"
	case "EACCES":
		description = "permission denied"
	case "EADDRNOTAVAIL":
		description = "address not available"
	case "EINVAL":
		description = "invalid argument"
	default:
		return failure
	}
	TsNodeNetSet(loop, failure, "syscall", TsNodeNetKey("listen"))
	TsNodeNetSet(loop, failure, "address", TsNodeNetKey(address))
	where := address
	if port != 0 {
		TsNodeNetSet(loop, failure, "port", TsNumberValue(float64(port)))
		where = address + ":" + strconv.Itoa(port)
	}
	message := "listen " + code + ": " + description
	if where != "" {
		message += " " + where
	}
	TsNodeNetSet(loop, failure, "message", TsNodeNetKey(message))
	return failure
}
func TsNodeNetTCPListenConfig(reusePort, ipv6Only bool) net.ListenConfig {
	config := net.ListenConfig{}
	if reusePort || ipv6Only {
		config.Control = func(network, address string, raw syscall.RawConn) error {
			host, _, _ := net.SplitHostPort(address)
			var socketErr error
			controlErr := raw.Control(func(fd uintptr) {
				if reusePort {
					socketErr = syscall.SetsockoptInt(int(fd), syscall.SOL_SOCKET, 0x0200, 1)
				}
				if socketErr == nil && ipv6Only && (strings.HasSuffix(network, "6") || strings.Contains(host, ":")) {
					socketErr = syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IPV6, syscall.IPV6_V6ONLY, 1)
				}
			})
			if controlErr != nil {
				return controlErr
			}
			return socketErr
		}
	}
	return config
}
