type TsNodeNetKeyLogFile struct{ Path string }

func (writer TsNodeNetKeyLogFile) Write(line []byte) (int, error) {
	file, err := os.OpenFile(writer.Path, os.O_WRONLY|os.O_CREATE|os.O_APPEND, 0600)
	if err != nil {
		return len(line), nil
	}
	_, _ = file.Write(line)
	_ = file.Close()
	return len(line), nil
}
func TsNodeNetKeyLogWriter(loop *TsLoop) io.Writer {
	TsNodeNetModule(loop)
	if !TsNodeNetSingleton.TlsKeylogConfigured {
		return nil
	}
	if !TsNodeNetSingleton.TlsKeylogWarned {
		TsNodeNetSingleton.TlsKeylogWarned = true
		process := TsNodeProcessModule(loop)
		emit := TsNodeNetGet(loop, process, "emitWarning")
		warning := TsNodeNetKey("Using --tls-keylog makes TLS connections insecure by writing secret key material to file " + TsNodeNetSingleton.TlsKeylogPath)
		if emit.Kind == TsFunctionKind {
			TsCall(loop, emit, warning)
		}
	}
	return TsNodeNetKeyLogFile{Path: TsNodeNetSingleton.TlsKeylogPath}
}
func TsNodeNetReadExecArgv(loop *TsLoop) {
	process := TsNodeProcessModule(loop)
	argv := TsNodeNetGet(loop, process, "execArgv")
	if argv.Kind != TsArrayKind {
		return
	}
	values := (*TsArray)(argv.Ref).Values
	for index := 0; index < len(values); index++ {
		arg := TsText(values[index])
		switch arg {
		case "--no-network-family-autoselection", "--no-enable-network-family-autoselection":
			TsNodeNetSingleton.DefaultAutoSelectFamily = false
		case "--network-family-autoselection", "--enable-network-family-autoselection":
			TsNodeNetSingleton.DefaultAutoSelectFamily = true
		case "--network-family-autoselection-attempt-timeout":
			if index+1 < len(values) {
				if n, err := strconv.Atoi(TsText(values[index+1])); err == nil && n >= 1 {
					if n < 10 {
						n = 10
					}
					TsNodeNetSingleton.DefaultAutoSelectFamilyAttemptTimeout = n
				}
				index++
			}
		case "--tls-keylog":
			if index+1 < len(values) {
				TsNodeNetSingleton.TlsKeylogConfigured = true
				TsNodeNetSingleton.TlsKeylogPath = TsText(values[index+1])
				index++
			}
		}
		if strings.HasPrefix(arg, "--network-family-autoselection-attempt-timeout=") {
			if n, err := strconv.Atoi(strings.TrimPrefix(arg, "--network-family-autoselection-attempt-timeout=")); err == nil && n >= 1 {
				if n < 10 {
					n = 10
				}
				TsNodeNetSingleton.DefaultAutoSelectFamilyAttemptTimeout = n
			}
		}
		if strings.HasPrefix(arg, "--tls-keylog=") {
			TsNodeNetSingleton.TlsKeylogConfigured = true
			TsNodeNetSingleton.TlsKeylogPath = strings.TrimPrefix(arg, "--tls-keylog=")
		}
	}
}
