func TsNodeDgramIPv4Interface(address string) ([4]byte, error) {
	var result [4]byte
	if address == "" {
		return result, nil
	}
	ip := net.ParseIP(address)
	if ip != nil && ip.To4() != nil {
		copy(result[:], ip.To4())
		return result, nil
	}
	iface, err := net.InterfaceByName(address)
	if err != nil {
		return result, errors.New("invalid IPv4 multicast interface")
	}
	addresses, err := iface.Addrs()
	if err != nil {
		return result, err
	}
	for _, entry := range addresses {
		candidate := entry.String()
		if slash := strings.IndexByte(candidate, '/'); slash >= 0 {
			candidate = candidate[:slash]
		}
		if parsed := net.ParseIP(candidate); parsed != nil && parsed.To4() != nil {
			copy(result[:], parsed.To4())
			return result, nil
		}
	}
	return result, errors.New("interface has no IPv4 address")
}
