	constructor.Construct = func(loop *TsLoop, args ...TsValue) TsValue { return TsNodeDgramCreate(loop, args) }
	constructor.ReceiverCall = func(loop *TsLoop, _ TsValue, args ...TsValue) TsValue { return TsNodeDgramCreate(loop, args) }
