	constructor.Properties.Set("prototype", TsObjectValue(TsNodeDgramSingleton.Prototype))
	TsNodeDgramSingleton.Constructor = TsFunctionValue(constructor)
	TsNodeDgramSingleton.Prototype.Set("constructor", TsNodeDgramSingleton.Constructor)
