	module.Set("Socket", TsNodeDgramSingleton.Constructor)
	module.Set("createSocket", TsNamedNativeMethod("createSocket", 2, func(loop *TsLoop, _ TsValue, args ...TsValue) TsValue { return TsNodeDgramCreate(loop, args) }))
