				record.Set("arguments", TsNodeCallTrackerFreezeArray(values))
				record.NonExtensible = true
				record.Descriptors = map[string]*TsDescriptor{"thisArg": {Writable: false, Configurable: false}, "arguments": {Writable: false, Configurable: false}}
