func TsNodeProcessOpenPSI() (int, uint64, bool) {
	paths := []string{"/proc/pressure/memory"}
	if data, err := os.ReadFile("/proc/self/cgroup"); err == nil {
		for _, line := range strings.Split(string(data), "\n") {
			if strings.HasPrefix(line, "0::") {
				group := strings.TrimPrefix(strings.TrimPrefix(line, "0::"), "/")
				path := "/sys/fs/cgroup/"
				if group != "" {
					path += group + "/"
				}
				paths = append(paths, path+"memory.pressure")
				break
			}
		}
	}
	for _, path := range paths {
		fd, err := unix.Open(path, unix.O_RDWR|unix.O_NONBLOCK|unix.O_CLOEXEC, 0)
		if err != nil {
			continue
		}
		var contents [256]byte
		n, readErr := unix.Pread(fd, contents[:], 0)
		lastTotal := uint64(0)
		if readErr == nil {
			if value, ok := TsNodeProcessPSISomeTotal(contents[:n]); ok {
				lastTotal = value
			}
		}
		trigger := []byte("some 150000 2000000\x00")
		written, writeErr := unix.Write(fd, trigger)
		if writeErr == nil && written == len(trigger) {
			return fd, lastTotal, true
		}
		_ = unix.Close(fd)
	}
	return -1, 0, false
}
func TsNodeProcessPSISomeTotal(contents []byte) (uint64, bool) {
	for _, line := range strings.Split(string(contents), "\n") {
		if !strings.HasPrefix(line, "some ") {
			continue
		}
		_, value, ok := strings.Cut(line, "total=")
		if !ok {
			return 0, false
		}
		end := 0
		for end < len(value) && value[end] >= '0' && value[end] <= '9' {
			end++
		}
		if end == 0 {
			return 0, false
		}
		total, err := strconv.ParseUint(value[:end], 10, 64)
		return total, err == nil
	}
	return 0, false
}
func TsNodeProcessPollPSI(loop *TsLoop, fd int, lastTotal uint64, watcher *TsNodeProcessMemoryPressureWatcher) {
	defer close(watcher.RuntimeFieldDone)
	defer unix.Close(fd)
	poll := []unix.PollFd{{Fd: int32(fd), Events: int16(unix.POLLPRI)}}
	for {
		select {
		case <-watcher.Stop:
			return
		default:
		}
		poll[0].Revents = 0
		count, err := unix.Poll(poll, 250)
		if err != nil {
			if err == unix.EINTR {
				continue
			}
			return
		}
		if count == 0 {
			continue
		}
		if poll[0].Revents&int16(unix.POLLERR|unix.POLLHUP) != 0 {
			return
		}
		if poll[0].Revents&int16(unix.POLLPRI) == 0 {
			continue
		}
		var contents [256]byte
		n, readErr := unix.Pread(fd, contents[:], 0)
		if readErr == nil {
			if total, ok := TsNodeProcessPSISomeTotal(contents[:n]); ok {
				if total < lastTotal || total-lastTotal < 150000 {
					continue
				}
				lastTotal = total
			}
		}
		select {
		case <-watcher.Stop:
			return
		default:
		}
		loop.Post(func() {
			process := TsNodeProcessSingleton.RuntimeFieldValue
			if process == nil {
				return
			}
			emit := process.RuntimeFieldGet(loop, "emit")
			if emit.Kind == TsFunctionKind {
				TsCallReceiver(loop, emit, TsObjectValue(process), TsNodeProcessString("memoryPressure"), TsNodeProcessString("critical"))
			}
		})
	}
}

