func TsNodeProcessTTY(fd int) bool {
	var file *os.File
	switch fd {
	case 0:
		file = os.Stdin
	case 1:
		file = os.Stdout
	case 2:
		file = os.Stderr
	}
	if file == nil {
		return false
	}
	info, err := file.Stat()
	return err == nil && info.Mode()&os.ModeCharDevice != 0
}
