	snapshot := map[string]any{"snapshot": map[string]any{"meta": meta, "node_count": 1, "edge_count": 0, "trace_function_count": 0, "trace_node_count": 0, "sample_count": 0, "location_count": 0, "root_index": 0}, "nodes": []uint64{9, 0, 1, uint64(memory.HeapAlloc), 0, 0, 0}, "edges": []uint64{}, "strings": []string{"synthetic Go heap snapshot"}, "trace_function_infos": []uint64{}, "trace_tree": []uint64{}, "samples": []uint64{}, "locations": []uint64{}}
