func TsHTTP2Transition(state, event uint8) (uint8, int) {
	protocol := TsHTTP2TransitionProtocolError
	closed := TsHTTP2TransitionStreamClosed
	switch state {
	case TsHTTP2StreamIdle:
		switch event {
		case TsHTTP2EventSendHeaders, TsHTTP2EventRecvHeaders:
			return TsHTTP2StreamOpen, 0
		case TsHTTP2EventSendHeadersEndStream:
			return TsHTTP2StreamHalfClosedLocal, 0
		case TsHTTP2EventRecvHeadersEndStream:
			return TsHTTP2StreamHalfClosedRemote, 0
		case TsHTTP2EventSendPushPromise:
			return TsHTTP2StreamReservedLocal, 0
		case TsHTTP2EventRecvPushPromise:
			return TsHTTP2StreamReservedRemote, 0
		default:
			return state, protocol
		}
	case TsHTTP2StreamReservedLocal:
		switch event {
		case TsHTTP2EventSendHeaders:
			return TsHTTP2StreamHalfClosedRemote, 0
		case TsHTTP2EventSendHeadersEndStream, TsHTTP2EventSendRst, TsHTTP2EventRecvRst:
			return TsHTTP2StreamClosed, 0
		default:
			return state, protocol
		}
	case TsHTTP2StreamReservedRemote:
		switch event {
		case TsHTTP2EventRecvHeaders:
			return TsHTTP2StreamHalfClosedLocal, 0
		case TsHTTP2EventRecvHeadersEndStream, TsHTTP2EventSendRst, TsHTTP2EventRecvRst:
			return TsHTTP2StreamClosed, 0
		default:
			return state, protocol
		}
	case TsHTTP2StreamOpen:
		switch event {
		case TsHTTP2EventSendEndStream, TsHTTP2EventSendHeadersEndStream:
			return TsHTTP2StreamHalfClosedLocal, 0
		case TsHTTP2EventRecvEndStream, TsHTTP2EventRecvHeadersEndStream:
			return TsHTTP2StreamHalfClosedRemote, 0
		case TsHTTP2EventSendRst, TsHTTP2EventRecvRst:
			return TsHTTP2StreamClosed, 0
		case TsHTTP2EventSendHeaders, TsHTTP2EventRecvHeaders:
			return TsHTTP2StreamOpen, 0
		default:
			return state, protocol
		}
	case TsHTTP2StreamHalfClosedLocal:
		switch event {
		case TsHTTP2EventRecvEndStream, TsHTTP2EventRecvHeadersEndStream, TsHTTP2EventSendRst, TsHTTP2EventRecvRst:
			return TsHTTP2StreamClosed, 0
		case TsHTTP2EventRecvHeaders:
			return TsHTTP2StreamHalfClosedLocal, 0
		default:
			return state, protocol
		}
	case TsHTTP2StreamHalfClosedRemote:
		switch event {
		case TsHTTP2EventSendEndStream, TsHTTP2EventSendHeadersEndStream, TsHTTP2EventSendRst, TsHTTP2EventRecvRst:
			return TsHTTP2StreamClosed, 0
		case TsHTTP2EventSendHeaders:
			return TsHTTP2StreamHalfClosedRemote, 0
		case TsHTTP2EventRecvEndStream, TsHTTP2EventRecvHeaders, TsHTTP2EventRecvHeadersEndStream:
			return state, closed
		default:
			return state, protocol
		}
	case TsHTTP2StreamClosed:
		if event == TsHTTP2EventSendRst || event == TsHTTP2EventRecvRst {
			return state, 0
		}
		return state, closed
	default:
		return state, protocol
	}
}
func TsHTTP2CanReceiveData(state uint8) bool {
	return state == TsHTTP2StreamIdle || state == TsHTTP2StreamOpen || state == TsHTTP2StreamHalfClosedLocal
}
func TsHTTP2CanSendData(state uint8) bool {
	return state == TsHTTP2StreamIdle || state == TsHTTP2StreamOpen || state == TsHTTP2StreamHalfClosedRemote
}

type TsHTTP2SendWindow struct{ Remaining int64 }
