func TsNodeHTTP2HeaderObject(loop *TsLoop, value TsValue) TsValue {
	out := TsNewObject()
	switch value.Kind {
	case TsArrayKind:
		array := (*TsArray)(value.Ref)
		for i := 0; i+1 < len(array.Values); i += 2 {
			name := strings.ToLower(TsText(array.Values[i]))
			item := array.Values[i+1]
			existing := out.RuntimeFieldGet(loop, name)
			if TsIsUndefined(existing) {
				out.Set(name, item)
			} else if existing.Kind == TsArrayKind {
				(*TsArray)(existing.Ref).Values = append((*TsArray)(existing.Ref).Values, item)
			} else {
				out.Set(name, TsArrayValue(&TsArray{Values: []TsValue{existing, item}}))
			}
		}
	case TsObjectKind, TsInstanceKind:
		source := (*TsObject)(value.Ref)
		for _, name := range source.Order {
			out.Set(strings.ToLower(name), source.Values[name])
		}
	}
	if TsNodeHTTP2Singleton.SensitiveHeaders != nil {
		symbol := TsValue{Kind: TsSymbolKind, Ref: unsafe.Pointer(TsNodeHTTP2Singleton.SensitiveHeaders)}
		sensitive := TsGet(loop, value, symbol)
		if !TsIsUndefined(sensitive) {
			TsSet(loop, TsObjectValue(out), symbol, sensitive)
		}
	}
	return TsObjectValue(out)
}
