func TsHTTP2NewRateLimit(burst, rate uint32) TsHTTP2RateLimit {
	return TsHTTP2RateLimit{Burst: burst, Rate: rate, Tokens: burst, LastRefill: time.Now()}
}
func (limit *TsHTTP2RateLimit) Drain() bool {
	elapsed := uint64(time.Since(limit.LastRefill) / time.Second)
	if elapsed > 0 {
		seconds := elapsed
		if seconds > math.MaxUint32 {
			seconds = math.MaxUint32
		}
		gain := seconds * uint64(limit.Rate)
		if gain > math.MaxUint32 {
			gain = math.MaxUint32
		}
		available := uint64(limit.Tokens) + gain
		if available > uint64(limit.Burst) {
			available = uint64(limit.Burst)
		}
		limit.Tokens = uint32(available)
		limit.LastRefill = limit.LastRefill.Add(time.Duration(seconds) * time.Second)
	}
	if limit.Tokens == 0 {
		return false
	}
	limit.Tokens--
	return true
}

