func TsNodeQUICBuildHeaders(loop *TsLoop, source, validator, strict TsValue, valid map[string]bool) TsValue {
	pairs := [][2]string{}
	if source.Kind == TsArrayKind {
		a := (*TsArray)(source.Ref)
		for i := 0; i+1 < len(a.Values); i += 2 {
			pairs = append(pairs, [2]string{TsText(a.Values[i]), TsText(a.Values[i+1])})
		}
	} else if TsNodeQUICObject(source) {
		o := (*TsObject)(source.Ref)
		for _, n := range o.Order {
			pairs = append(pairs, [2]string{n, TsText(o.Values[n])})
		}
	}
	var regular, pseudo strings.Builder
	count := 0
	for _, pair := range pairs {
		name, value := strings.ToLower(pair[0]), pair[1]
		if name == "" {
			continue
		}
		if strings.ContainsAny(name, "\r\n\x00") || strings.ContainsAny(value, "\r\n\x00") {
			panic(TsThrown{TsFSException("TypeError", "ERR_INVALID_CHAR", "Invalid HTTP/2 header content")})
		}
		if strings.HasPrefix(name, ":") {
			if !valid[name] {
				panic(TsThrown{TsNodeQUICError("ERR_HTTP2_INVALID_PSEUDOHEADER", "Invalid HTTP/2 pseudo-header")})
			}
			if validator.Kind == TsFunctionKind {
				result := TsCall(loop, validator, TsNodeQUICKey(name), TsNodeQUICKey(value))
				if !TsIsUndefined(result) && !TsNullish(result) {
					panic(TsThrown{result})
				}
			}
			pseudo.WriteString(name)
			pseudo.WriteByte(0)
			pseudo.WriteString(value)
			pseudo.WriteByte(0)
			pseudo.WriteByte(0)
		} else {
			if name == "connection" || name == "upgrade" || name == "http2-settings" || name == "keep-alive" || name == "proxy-connection" || name == "transfer-encoding" {
				panic(TsThrown{TsNodeQUICError("ERR_HTTP2_INVALID_CONNECTION_HEADERS", "HTTP/1 connection-specific headers are forbidden")})
			}
			regular.WriteString(name)
			regular.WriteByte(0)
			regular.WriteString(value)
			regular.WriteByte(0)
			regular.WriteByte(0)
		}
		count++
	}
	out := &TsArray{Values: []TsValue{TsNodeQUICKey(pseudo.String() + regular.String()), TsNumberValue(float64(count))}}
	_ = strict
	return TsArrayValue(out)
}
