func TsNodeTestCreateNode(loop *TsLoop, name string, parent *TsNodeTestNode, suite bool, options TsValue, ownTags []TsValue) *TsNodeTestNode {
	node := &TsNodeTestNode{Name: name, Parent: parent, Suite: suite, Options: options, Hooks: map[string][]*TsNodeTestHookState{}, Failure: TsU, ExpectedFailureMatch: TsU, ExpectedFailureLabel: TsU}
	if parent != nil {
		node.OnlyMode = parent.OnlyMode
	}
	object := TsNewObject()
	if suite {
		object.Prototype = TsObjectValue(TsNodeTestSingleton.SuiteProto)
	} else {
		object.Prototype = TsObjectValue(TsNodeTestSingleton.TestProto)
	}
	node.Object = object
	TsNodeTestSingleton.Nodes[object] = node
	if parent != nil {
		node.Tags = append(node.Tags, parent.Tags...)
	}
	seen := map[string]bool{}
	for _, tag := range node.Tags {
		seen[TsText(tag)] = true
	}
	for _, tag := range ownTags {
		normalized := strings.ToLower(TsText(tag))
		if !seen[normalized] {
			seen[normalized] = true
			node.Tags = append(node.Tags, TsNodeTestKey(normalized))
		}
	}
	if TsNodeTestIsJSObject(options) {
		skip := TsNodeTestGet(loop, options, "skip")
		todo := TsNodeTestGet(loop, options, "todo")
		node.Skipped = TsTruthy(skip)
		node.Todo = TsTruthy(todo) || (parent != nil && parent.Todo)
		node.Only = TsTruthy(TsNodeTestGet(loop, options, "only"))
		if skip.Kind == TsStringKind {
			node.Message = TsText(skip)
		} else if todo.Kind == TsStringKind {
			node.Message = TsText(todo)
		}
		enabled, match, label := TsNodeTestParseExpectedFailure(loop, TsNodeTestGet(loop, options, "expectFailure"))
		if enabled {
			node.ExpectedFailure = true
			node.ExpectedFailureMatch = match
			node.ExpectedFailureLabel = label
		} else if parent != nil && parent.ExpectedFailure {
			node.ExpectedFailure = true
			node.ExpectedFailureMatch = parent.ExpectedFailureMatch
			node.ExpectedFailureLabel = parent.ExpectedFailureLabel
		}
	}
	return node
}
