func TsNodeTestPlanCountState(loop *TsLoop, node *TsNodeTestNode, plan *TsNodeTestPlanState) {
	if node == nil || plan == nil {
		return
	}
	plan.Actual++
	if plan.Actual > plan.Expected {
		node.Failure = TsNodeTestError(fmt.Sprintf("plan expected %d assertions but received %d", plan.Expected, plan.Actual))
	}
	if plan.Pending != nil && plan.Actual >= plan.Expected {
		pending := plan.Pending
		plan.Pending = nil
		if plan.Timer != nil {
			loop.ClearTimeout(TsTaskValue(plan.Timer))
			plan.Timer = nil
		}
		pending.Settle(TsResult{TsU, false})
	}
}
