func TsNodeTestPlanCheck(loop *TsLoop, node *TsNodeTestNode) TsValue {
	plan := node.Plan
	if plan == nil || plan.Actual == plan.Expected {
		return TsU
	}
	if plan.Actual > plan.Expected || !TsTruthy(plan.Wait) {
		return TsNodeTestError(fmt.Sprintf("plan expected %d assertions but received %d", plan.Expected, plan.Actual))
	}
	promise := loop.Promise()
	plan.Pending = promise
	if TsIsNumeric(plan.Wait) {
		wait := TsNumber(plan.Wait)
		plan.Timer = TsNodeTestRealTimeout(loop, wait, func() {
			if plan.Pending == promise {
				plan.Pending = nil
				plan.Timer = nil
				promise.Settle(TsResult{TsNodeTestError(fmt.Sprintf("plan timed out after %gms with %d assertions when expecting %d", wait, plan.Actual, plan.Expected)), true})
			}
		})
	}
	return TsPromiseValue(promise)
}
