func TsNodeTestValidateOptions(loop *TsLoop, options TsValue) []TsValue {
	validate := func(name string, args ...TsValue) {
		TsCall(loop, TsNodeTestGet(loop, TsInternalValidatorsModule(loop), name), args...)
	}
	timeout, signal := TsNodeTestGet(loop, options, "timeout"), TsNodeTestGet(loop, options, "signal")
	if !TsIsUndefined(signal) {
		validate("validateAbortSignal", signal, TsNodeTestKey("options.signal"))
	}
	if !TsNullish(timeout) && !(TsIsNumeric(timeout) && math.IsInf(TsNumber(timeout), 1)) {
		validate("validateNumber", timeout, TsNodeTestKey("options.timeout"), TsNumberValue(0), TsNumberValue(2147483647))
	}
	concurrency := TsNodeTestGet(loop, options, "concurrency")
	if !TsNullish(concurrency) && concurrency.Kind != TsBooleanKind {
		if TsIsNumeric(concurrency) {
			validate("validateUint32", concurrency, TsNodeTestKey("options.concurrency"), TsBooleanValue(true))
		} else {
			TsInternalValidatorInvalidType("options.concurrency", "a boolean or number", concurrency)
		}
	}
	plan := TsNodeTestGet(loop, options, "plan")
	if !TsIsUndefined(plan) {
		validate("validateUint32", plan, TsNodeTestKey("options.plan"))
	}
	tags := TsNodeTestGet(loop, options, "tags")
	if TsIsUndefined(tags) {
		return nil
	}
	validate("validateArray", tags, TsNodeTestKey("options.tags"))
	array := (*TsArray)(tags.Ref)
	out := make([]TsValue, 0, array.Length())
	seen := map[string]bool{}
	for index := 0; index < array.Length(); index++ {
		tag := array.At(index)
		name := "options.tags[" + strconv.Itoa(index) + "]"
		validate("validateString", tag, TsNodeTestKey(name))
		normalized := strings.ToLower(TsText(tag))
		if normalized == "" {
			TsInternalValidatorInvalidValue(name, "must not be an empty string", tag)
		}
		if !seen[normalized] {
			seen[normalized] = true
			out = append(out, TsNodeTestKey(normalized))
		}
	}
	if len(out) > 0 {
		TsNodeTestEmitTagsWarning(loop)
	}
	return out
}
func TsNodeTestParseExpectedFailure(loop *TsLoop, value TsValue) (bool, TsValue, TsValue) {
	if TsIsUndefined(value) || value.Kind == TsBooleanKind && !TsTruthy(value) {
		return false, TsU, TsU
	}
	if value.Kind == TsStringKind {
		return true, TsU, value
	}
	if value.Kind == TsFunctionKind || value.Kind == TsRegExpKind {
		return true, value, TsU
	}
	if TsNullish(value) {
		TsInternalValidatorInvalidType("options.expectFailure", "an object", value)
	}
	if !TsNodeTestIsJSObject(value) {
		return true, TsU, TsU
	}
	keys := TsObjectKeys(loop, value)
	if keys.Length() == 0 {
		TsInternalValidatorInvalidValue("options.expectFailure", "must not be an empty object", value)
	}
	onlyOptions := true
	for index := 0; index < keys.Length(); index++ {
		key := keys.At(index)
		name := TsText(key)
		if name != "match" && name != "label" {
			onlyOptions = false
			break
		}
	}
	if !onlyOptions {
		return true, value, TsU
	}
	return true, TsNodeTestGet(loop, value, "match"), TsNodeTestGet(loop, value, "label")
}
func TsNodeTestRegister(loop *TsLoop, args []TsValue, parent *TsNodeTestNode, suite bool, mode string) TsValue {
	name, options, fn := TsNodeTestParseArgs(loop, args)
	ownTags := TsNodeTestValidateOptions(loop, options)
	if parent == nil {
		parent = TsNodeTestCurrent(loop)
	}
	if parent == nil {
		parent = TsNodeTestSingleton.Root
	}
	node := TsNodeTestCreateNode(loop, name, parent, suite, options, ownTags)
	if mode == "skip" {
		node.Skipped = true
	}
	if mode == "todo" {
		node.Todo = true
	}
	if mode == "only" {
		node.Only = true
	}
	if parent.OnlyMode && !node.Only && !suite {
		node.Filtered = true
	}
	var result TsValue
	if suite && node.Skipped {
		result = TsPromiseValue(loop.Resolved(TsU, false))
	} else {
		result = TsNodeTestExecute(loop, node, fn, suite)
	}
	if parent != nil {
		parent.Children = append(parent.Children, result)
	}
	return result
}
