		TsNodeTestSingleton.SuiteProto = TsNewObject()
		TsNodeTestSingleton.MockProto = TsNewObject()
		TsNodeTestSingleton.MockFunctionProto = TsNewObject()
		TsNodeTestSingleton.MockPropertyProto = TsNewObject()
		TsNodeTestMockPropertyInit()
