var TsNodeTLSCompatModules struct {
	sync.Once
	Common, Wrap               TsValue
	CommonWarning, WrapWarning sync.Once
}

func TsNodeTLSCompatTranslatePeerCertificate(loop *TsLoop, certificate TsValue) TsValue {
	if !TsTruthy(certificate) {
		return TsNull
	}
	issuer := TsGet(loop, certificate, TsStringReference(TsStringUTF8("issuerCertificate")))
	if !TsNullish(issuer) && !TsStrictEqual(issuer, certificate) {
		TsSet(loop, certificate, TsStringReference(TsStringUTF8("issuerCertificate")), TsNodeTLSCompatTranslatePeerCertificate(loop, issuer))
	}
	info := TsGet(loop, certificate, TsStringReference(TsStringUTF8("infoAccess")))
	if !TsNullish(info) {
		parsed := TsNewObject()
		for _, line := range strings.Split(TsText(info), "\n") {
			colon := strings.IndexByte(line, ':')
			if colon < 0 {
				continue
			}
			key, value := line[:colon], line[colon+1:]
			parsedValue := TsStringReference(TsStringUTF8(value))
			if len(value) != 0 && value[0] == '"' {
				parsedValue = TsJSONBuiltin(loop, "parse", []TsValue{TsStringReference(TsStringUTF8(value))})
			}
			previous := TsGet(loop, TsObjectValue(parsed), TsStringReference(TsStringUTF8(key)))
			if previous.Kind == TsArrayKind {
				array := (*TsArray)(previous.Ref)
				array.Values = append(array.Values, parsedValue)
			} else {
				parsed.Set(key, TsArrayValue(&TsArray{Values: []TsValue{parsedValue}}))
			}
		}
		TsSet(loop, certificate, TsStringReference(TsStringUTF8("infoAccess")), TsObjectValue(parsed))
	}
	return certificate
}

func TsNodeTLSCompatModule(loop *TsLoop, name string) TsValue {
	TsNodeTLSCompatModules.Do(func() {
		tls := TsNodeTLSModule(loop)
		common := TsNewObject()
		common.Set("SecureContext", TsGet(loop, tls, TsStringReference(TsStringUTF8("SecureContext"))))
		common.Set("createSecureContext", TsGet(loop, tls, TsStringReference(TsStringUTF8("createSecureContext"))))
		common.Set("translatePeerCertificate", TsNamedNativeMethod("translatePeerCertificate", 1, func(loop *TsLoop, _ TsValue, args ...TsValue) TsValue {
			return TsNodeTLSCompatTranslatePeerCertificate(loop, TsArg(args, 0))
		}))
		wrap := TsNewObject()
		for _, property := range []string{"TLSSocket", "Server", "createServer", "connect"} {
			wrap.Set(property, TsGet(loop, tls, TsStringReference(TsStringUTF8(property))))
		}
		TsNodeTLSCompatModules.Common = TsObjectValue(common)
		TsNodeTLSCompatModules.Wrap = TsObjectValue(wrap)
	})
	process := TsNodeProcessModule(loop)
	warning := "The _tls_common module is deprecated. Use 'node:tls' instead."
	warningOnce := &TsNodeTLSCompatModules.CommonWarning
	if name == "_tls_wrap" {
		warning = "The _tls_wrap module is deprecated. Use 'node:tls' instead."
		warningOnce = &TsNodeTLSCompatModules.WrapWarning
	}
	warningOnce.Do(func() {
		emitWarning := TsGet(loop, process, TsStringReference(TsStringUTF8("emitWarning")))
		if emitWarning.Kind == TsFunctionKind {
			TsCallReceiver(loop, emitWarning, process, TsStringReference(TsStringUTF8(warning)), TsStringReference(TsStringUTF8("DeprecationWarning")), TsStringReference(TsStringUTF8("DEP0192")))
		}
	})
	if name == "_tls_wrap" {
		return TsNodeTLSCompatModules.Wrap
	}
	return TsNodeTLSCompatModules.Common
}
