func TsBigIntValue(number *big.Int) TsValue {
	return TsValue{Kind: TsBigIntKind, Ref: unsafe.Pointer(number)}
}
func TsBigIntSigned(number int64) TsValue    { return TsBigIntValue(big.NewInt(number)) }
func TsBigIntUnsigned(number uint64) TsValue { return TsBigIntValue(new(big.Int).SetUint64(number)) }
func TsBigIntParse(text string) (*big.Int, bool) {
	text = strings.TrimSpace(strings.Trim(text, "\ufeff"))
	if text == "" {
		return new(big.Int), true
	}
	base := 10
	unsigned := text
	if strings.HasPrefix(unsigned, "+") || strings.HasPrefix(unsigned, "-") {
		unsigned = unsigned[1:]
	}
	if len(unsigned) > 2 && unsigned[0] == '0' {
		switch unsigned[1] {
		case 'x', 'X', 'o', 'O', 'b', 'B':
			if unsigned != text {
				return nil, false
			}
			base = 0
		}
	}
	if strings.ContainsAny(text, "._") {
		return nil, false
	}
	number, ok := new(big.Int).SetString(text, base)
	return number, ok
}
func TsBigIntFrom(loop *TsLoop, value TsValue) TsValue {
	value = TsToPrimitive(loop, value)
	switch value.Kind {
	case TsBigIntKind:
		return value
	case TsStringKind:
		number, ok := TsBigIntParse(TsText(value))
		if !ok {
			panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "SyntaxError", Message: "Cannot convert string to a BigInt"})})
		}
		return TsBigIntValue(number)
	case TsBooleanKind:
		if value.Number != 0 {
			return TsBigIntSigned(1)
		}
		return TsBigIntSigned(0)
	}
	if TsIsSigned(value) {
		return TsBigIntSigned(int64(math.Float64bits(value.Number)))
	}
	if TsIsUnsigned(value) {
		return TsBigIntUnsigned(math.Float64bits(value.Number))
	}
	if TsIsNumeric(value) {
		number := TsNumber(value)
		if math.IsNaN(number) || math.IsInf(number, 0) || math.Trunc(number) != number {
			panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "RangeError", Message: "A non-integer number cannot be converted to BigInt"})})
		}
		integer, _ := new(big.Float).SetFloat64(number).Int(nil)
		return TsBigIntValue(integer)
	}
	panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "Cannot convert value to BigInt"})})
}
func TsBigIntLiteral(text string) TsValue {
	number, ok := TsBigIntParse(strings.ReplaceAll(strings.TrimSuffix(text, "n"), "_", ""))
	if !ok {
		panic("Invalid BigInt literal")
	}
	return TsBigIntValue(number)
}
func TsBigIntCompare(a, b TsValue) (int, bool) {
	if a.Kind != TsBigIntKind {
		comparison, valid := TsBigIntCompare(b, a)
		return -comparison, valid
	}
	integer := (*big.Int)(a.Ref)
	if b.Kind == TsBigIntKind {
		return integer.Cmp((*big.Int)(b.Ref)), true
	}
	if b.Kind == TsStringKind {
		number, ok := TsBigIntParse(TsText(b))
		if !ok {
			return 0, false
		}
		return integer.Cmp(number), true
	}
	if b.Kind == TsBooleanKind || b.Kind == TsNullKind {
		b = TsNumberValue(TsNumber(b))
	}
	if TsIsSigned(b) {
		return integer.Cmp(big.NewInt(int64(math.Float64bits(b.Number)))), true
	}
	if TsIsUnsigned(b) {
		return integer.Cmp(new(big.Int).SetUint64(math.Float64bits(b.Number))), true
	}
	if !TsIsNumeric(b) {
		return 0, false
	}
	number := TsNumber(b)
	if math.IsNaN(number) {
		return 0, false
	}
	if math.IsInf(number, 1) {
		return -1, true
	}
	if math.IsInf(number, -1) {
		return 1, true
	}
	return new(big.Rat).SetInt(integer).Cmp(new(big.Rat).SetFloat64(number)), true
}
func TsBigIntBinary(loop *TsLoop, op string, left, right TsValue) TsValue {
	switch op {
	case "===", "!==":
		equal := left.Kind == TsBigIntKind && right.Kind == TsBigIntKind && (*big.Int)(left.Ref).Cmp((*big.Int)(right.Ref)) == 0
		if op == "!==" {
			equal = !equal
		}
		return TsBooleanValue(equal)
	case "==", "!=":
		equal := TsLooseEqual(loop, left, right)
		if op == "!=" {
			equal = !equal
		}
		return TsBooleanValue(equal)
	case "<", "<=", ">", ">=":
		left = TsToPrimitive(loop, left)
		right = TsToPrimitive(loop, right)
		if left.Kind == TsSymbolKind || right.Kind == TsSymbolKind {
			TsPropertyFailure("Cannot convert Symbol to number")
		}
		comparison, valid := TsBigIntCompare(left, right)
		if !valid {
			return TsBooleanValue(false)
		}
		switch op {
		case "<":
			return TsBooleanValue(comparison < 0)
		case "<=":
			return TsBooleanValue(comparison <= 0)
		case ">":
			return TsBooleanValue(comparison > 0)
		default:
			return TsBooleanValue(comparison >= 0)
		}
	case "+":
		left = TsToPrimitive(loop, left)
		right = TsToPrimitive(loop, right)
		if left.Kind == TsStringKind || right.Kind == TsStringKind {
			return TsStringReference(TsStringUTF8(TsText(left) + TsText(right)))
		}
	}
	if left.Kind != TsBigIntKind || right.Kind != TsBigIntKind {
		panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "Cannot mix BigInt and other types"})})
	}
	a, b := (*big.Int)(left.Ref), (*big.Int)(right.Ref)
	out := new(big.Int)
	switch op {
	case "+":
		out.Add(a, b)
	case "-":
		out.Sub(a, b)
	case "*":
		out.Mul(a, b)
	case "/", "%":
		if b.Sign() == 0 {
			panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "RangeError", Message: "Division by zero"})})
		}
		if op == "/" {
			out.Quo(a, b)
		} else {
			out.Rem(a, b)
		}
	case "&":
		out.And(a, b)
	case "|":
		out.Or(a, b)
	case "^":
		out.Xor(a, b)
	case ">>>":
		panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "BigInts have no unsigned right shift"})})
	case "<<", ">>":
		shift := new(big.Int).Abs(b)
		rightShift := (op == ">>") != (b.Sign() < 0)
		if rightShift && (!shift.IsUint64() || shift.Uint64() > uint64(a.BitLen()+1)) {
			if a.Sign() < 0 {
				return TsBigIntSigned(-1)
			}
			return TsBigIntSigned(0)
		}
		if !shift.IsUint64() || shift.Uint64() > 1<<30 {
			panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "RangeError", Message: "Maximum BigInt size exceeded"})})
		}
		if rightShift {
			out.Rsh(a, uint(shift.Uint64()))
		} else {
			out.Lsh(a, uint(shift.Uint64()))
		}
	case "**":
		if b.Sign() < 0 {
			panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "RangeError", Message: "Exponent must be positive"})})
		}
		if !b.IsUint64() || (a.BitLen() > 1 && b.Uint64() > uint64(1<<30)/uint64(a.BitLen())) {
			panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "RangeError", Message: "Maximum BigInt size exceeded"})})
		}
		out.Exp(a, b, nil)
	default:
		panic("Unsupported BigInt operator")
	}
	return TsBigIntValue(out)
}
func TsNegate(value TsValue) TsValue {
	if value.Kind == TsBigIntKind {
		return TsBigIntValue(new(big.Int).Neg((*big.Int)(value.Ref)))
	}
	return TsNumberValue(-TsNumber(value))
}
func TsIncrementOperand(loop *TsLoop, value TsValue) TsValue {
	value = TsToPrimitive(loop, value)
	if value.Kind == TsBigIntKind {
		return value
	}
	return TsNumberValue(TsNumber(value))
}
func TsIncrement(loop *TsLoop, value TsValue, op string) TsValue {
	if value.Kind == TsBigIntKind {
		return TsBigIntBinary(loop, op, value, TsBigIntSigned(1))
	}
	return TsBinary(loop, op, value, TsNumberValue(1))
}
func TsBigIntProperty(value TsValue, name string) TsValue {
	switch name {
	case "valueOf":
		return TsFunctionValue(TsFunc(func(loop *TsLoop, args ...TsValue) TsValue { return value }))
	case "toString", "toLocaleString":
		return TsFunctionValue(TsFunc(func(loop *TsLoop, args ...TsValue) TsValue {
			radix := 10
			if name == "toString" && !TsIsUndefined(TsArg(args, 0)) {
				radix = int(TsNumber(TsArg(args, 0)))
				if radix < 2 || radix > 36 {
					panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "RangeError", Message: "radix must be between 2 and 36"})})
				}
			}
			return TsStringReference(TsStringUTF8((*big.Int)(value.Ref).Text(radix)))
		}))
	}
	return TsU
}

var TsBigIntIntrinsics struct {
	sync.Once
	Function  *TsFunction
	Prototype *TsObject
}

func TsBigIntFunction(loop *TsLoop) TsValue {
	TsBigIntIntrinsics.Do(func() {
		prototype := TsNewObject()
		prototype.Prototype = TsObjectPrototype(loop)
		prototype.BoxedPrimitive = TsBigIntSigned(0)
		function := TsFunc(func(loop *TsLoop, args ...TsValue) TsValue { return TsBigIntFrom(loop, TsArg(args, 0)) })
		function.Name = "BigInt"
		function.Length = 1
		function.Properties = TsNewObject()
		function.Properties.Set("prototype", TsObjectValue(prototype))
		function.Properties.Descriptors = map[string]*TsDescriptor{"prototype": {}}
		prototype.Set("constructor", TsFunctionValue(function))
		prototype.Descriptors = map[string]*TsDescriptor{"constructor": {Writable: true, Configurable: true}}
		for _, method := range []string{"asIntN", "asUintN"} {
			name := method
			function.Properties.Set(name, TsFunctionValue(TsFunc(func(loop *TsLoop, args ...TsValue) TsValue {
				width := TsToIndex(loop, TsArg(args, 0))
				value := TsArg(args, 1)
				if TsIsNumeric(value) {
					panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "Cannot convert number to a BigInt"})})
				}
				number := (*big.Int)(TsBigIntFrom(loop, value).Ref)
				if width == 0 {
					return TsBigIntSigned(0)
				}
				if width > 1<<30 {
					panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "RangeError", Message: "Maximum BigInt size exceeded"})})
				}
				modulus := new(big.Int).Lsh(big.NewInt(1), uint(width))
				result := new(big.Int).Mod(number, modulus)
				if name == "asIntN" && result.Bit(width-1) != 0 {
					result.Sub(result, modulus)
				}
				return TsBigIntValue(result)
			})))
			function.Properties.Descriptors[name] = &TsDescriptor{Writable: true, Configurable: true}
		}
		TsBigIntIntrinsics.Function = function
		TsBigIntIntrinsics.Prototype = prototype
	})
	return TsFunctionValue(TsBigIntIntrinsics.Function)
}
func TsConvertBigInt(loop *TsLoop, value TsValue, kind string) TsValue {
	integer := (*big.Int)(value.Ref)
	switch kind {
	case "string":
		return TsStringReference(TsStringUTF8(integer.String()))
	case "boolean":
		return TsBooleanValue(integer.Sign() != 0)
	case "number", "float32":
		number, _ := new(big.Float).SetInt(integer).Float64()
		if math.IsInf(number, 0) {
			TsNumericRangeFailure(kind)
		}
		return TsConvertValue(loop, TsNumberValue(number), kind, true)
	}
	if strings.HasPrefix(kind, "uint") {
		if !integer.IsUint64() {
			TsNumericRangeFailure(kind)
		}
		return TsConvertValue(loop, TsUint64Value(integer.Uint64()), kind, true)
	}
	if !integer.IsInt64() {
		TsNumericRangeFailure(kind)
	}
	return TsConvertValue(loop, TsInt64Value(integer.Int64()), kind, true)
}

func TsCallReceiver(loop *TsLoop, value, receiver TsValue, args ...TsValue) TsValue {
	if value.Kind == TsFunctionKind {
		function := (*TsFunction)(value.Ref)
		if function.ReceiverCall != nil {
			return function.ReceiverCall(loop, receiver, args...)
		}
	}
	return TsCall(loop, value, args...)
}
func TsFunctionGet(loop *TsLoop, value TsValue, name string) TsValue {
	function := (*TsFunction)(value.Ref)
	if object := function.ReadProperties(); object != nil {
		if TsOwnObjectProperty(object, name) {
			if descriptor := object.Descriptors[name]; descriptor != nil && descriptor.Accessor {
				if TsIsUndefined(descriptor.Getter) {
					return TsU
				}
				return TsCallReceiver(loop, descriptor.Getter, value)
			}
			return object.Values[name]
		}
	}
	if function.MetadataRef.Load() != nil {
		return TsPrototypeLookup(loop, value, TsPrototypeOf(loop, value), name)
	}
	if name == "prototype" {
		return TsFunctionPrototype(loop, value)
	}
	if name == "name" {
		return TsStringReference(TsStringUTF8(function.Name))
	}
	if name == "length" {
		return TsNumberValue(float64(function.Length))
	}
	return TsPrototypeLookup(loop, value, TsPrototypeOf(loop, value), name)
}
func TsNamedNativeMethod(name string, length int, call func(*TsLoop, TsValue, ...TsValue) TsValue) TsValue {
	function := &TsFunction{ReceiverCall: call, Properties: TsNewObject()}
	function.Properties.Set("name", TsStringReference(TsStringUTF8(name)))
	function.Properties.Set("length", TsNumberValue(float64(length)))
	function.Properties.Descriptors = map[string]*TsDescriptor{"name": {Configurable: true}, "length": {Configurable: true}}
	return TsFunctionValue(function)
}
func TsNativeMethod(call func(*TsLoop, TsValue, ...TsValue) TsValue) TsValue {
	return TsFunctionValue(&TsFunction{ReceiverCall: call})
}

var TsNativeClasses struct {
	sync.Once
	Classes map[string]*TsClass
}

func TsNativeClass(loop *TsLoop, name string) *TsClass {
	TsNativeClasses.Do(func() {
		TsNativeClasses.Classes = map[string]*TsClass{}
		for _, name := range []string{"Stats", "BigIntStats", "StatFs", "BigIntStatFs", "Dirent", "Dir", "FSWatcher", "StatWatcher", "FSEvent", "ReadStream", "WriteStream", "Buffer", "Date", "AbortSignal", "AbortController", "FileHandle", "Blob", "File", "ReadableStream", "ReadableStreamDefaultReader", "ReadableStreamBYOBReader"} {
			class := &TsClass{Builtin: name, Static: TsInstanceValue(TsNewProperties()), NativePrototype: TsNewObject()}
			TsNativeClasses.Classes[name] = class
			class.NativePrototype.Set("constructor", TsClassValue(class))
			properties := TsInstanceProperties(class.Static)
			properties.Define("prototype")
			properties.Extra["prototype"] = TsObjectValue(class.NativePrototype)
			class.Construct = func(loop *TsLoop, args ...TsValue) TsValue {
				switch name {
				case "Blob":
					return TsBlobConstruct(loop, args)
				case "File":
					return TsNodeBufferFileConstruct(loop, args)
				case "Date":
					return TsDateConstruct(loop, args)
				case "Stats":
					return TsFSConstructStats(loop, args)
				case "BigIntStats":
					return TsFSConstructBigIntStats(loop, args)
				case "StatFs":
					return TsFSConstructStatFS(loop, args, false)
				case "BigIntStatFs":
					return TsFSConstructStatFS(loop, args, true)
				case "Dirent":
					return TsFSConstructDirent(loop, args)
				case "ReadStream", "WriteStream":
					return TsFSCreateStream(loop, TsArg(args, 0), TsArg(args, 1), name == "ReadStream")
				case "Buffer":
					if TsIsNumeric(TsArg(args, 0)) {
						return TsNodeBufferAllocate(loop, args, false)
					}
					return TsNodeBufferFrom(loop, args)
				case "AbortController":
					return TsAbortController(loop)
				default:
					panic(TsThrown{TsFSException("TypeError", "ERR_ILLEGAL_CONSTRUCTOR", "Illegal constructor")})
				}
			}
		}
		TsInstallDateClass(TsNativeClasses.Classes["Date"])
		for _, name := range []string{"Stats", "BigIntStats", "Dirent"} {
			class := TsNativeClasses.Classes[name]
			for _, predicate := range []string{"isFile", "isDirectory", "isSymbolicLink", "isBlockDevice", "isCharacterDevice", "isFIFO", "isSocket"} {
				method := predicate
				class.NativePrototype.Set(method, TsNamedNativeMethod(method, 0, func(loop *TsLoop, receiver TsValue, args ...TsValue) TsValue {
					if receiver.Kind != TsObjectKind {
						TsFSInvalid("this", "a filesystem metadata object")
					}
					object := (*TsObject)(receiver.Ref)
					mode := object.NativeMode
					if class.Builtin == "Dirent" && object.NativeClass != class {
						mode = os.ModeIrregular
					}
					if class.Builtin == "Stats" || class.Builtin == "BigIntStats" {
						value := object.RuntimeFieldGet(loop, "mode")
						bits := uint32(0)
						if class.Builtin == "BigIntStats" {
							if value.Kind != TsBigIntKind {
								panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "Cannot convert value to a BigInt"})})
							}
							bits = uint32((*big.Int)(value.Ref).Int64())
						} else {
							if value.Kind == TsBigIntKind {
								panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "Cannot convert a BigInt value to a number"})})
							}
							bits = TsNumberUint32(TsNumber(value))
						}
						switch bits & syscall.S_IFMT {
						case syscall.S_IFDIR:
							mode = os.ModeDir
						case syscall.S_IFLNK:
							mode = os.ModeSymlink
						case syscall.S_IFBLK:
							mode = os.ModeDevice
						case syscall.S_IFCHR:
							mode = os.ModeDevice | os.ModeCharDevice
						case syscall.S_IFIFO:
							mode = os.ModeNamedPipe
						case syscall.S_IFSOCK:
							mode = os.ModeSocket
						case syscall.S_IFREG:
							mode = 0
						default:
							mode = os.ModeIrregular
						}
					}
					answer := false
					switch method {
					case "isFile":
						answer = mode.IsRegular()
					case "isDirectory":
						answer = mode.IsDir()
					case "isSymbolicLink":
						answer = mode&os.ModeSymlink != 0
					case "isBlockDevice":
						answer = mode&os.ModeDevice != 0 && mode&os.ModeCharDevice == 0
					case "isCharacterDevice":
						answer = mode&os.ModeCharDevice != 0
					case "isFIFO":
						answer = mode&os.ModeNamedPipe != 0
					case "isSocket":
						answer = mode&os.ModeSocket != 0
					}
					return TsBooleanValue(answer)
				}))
			}
		}
		buffer := TsNativeClasses.Classes["Buffer"]
		methods := []string{}
		for _, operation := range []string{"read", "write"} {
			for _, spec := range []string{"UInt", "Uint", "Int", "UInt16", "Uint16", "Int16", "UInt32", "Uint32", "Int32", "Float", "Double", "BigUInt64", "BigUint64", "BigInt64"} {
				for _, endian := range []string{"LE", "BE"} {
					methods = append(methods, operation+spec+endian)
				}
			}
			for _, spec := range []string{"UInt8", "Uint8", "Int8"} {
				methods = append(methods, operation+spec)
			}
		}
		for _, name := range methods {
			method := name
			buffer.NativePrototype.Set(method, TsNativeMethod(func(loop *TsLoop, receiver TsValue, args ...TsValue) TsValue {
				if receiver.Kind != TsTypedArrayKind || !(*TsTypedArray)(receiver.Ref).NodeBuffer {
					TsFSInvalid("this", "a Buffer")
				}
				return TsCall(loop, TsNodeBufferGet(receiver, method), args...)
			}))
		}
		for _, name := range []string{"toString", "toLocaleString", "toJSON", "inspect", "equals", "compare", "copy", "fill", "write", "slice", "subarray", "includes", "indexOf", "lastIndexOf", "swap16", "swap32", "swap64", "asciiSlice", "asciiWrite", "base64Slice", "base64Write", "base64urlSlice", "base64urlWrite", "hexSlice", "hexWrite", "latin1Slice", "latin1Write", "ucs2Slice", "ucs2Write", "utf16leSlice", "utf16leWrite", "utf8Slice", "utf8Write"} {
			method := name
			buffer.NativePrototype.Set(method, TsNativeMethod(func(loop *TsLoop, receiver TsValue, args ...TsValue) TsValue {
				if receiver.Kind != TsTypedArrayKind || !(*TsTypedArray)(receiver.Ref).NodeBuffer {
					TsFSInvalid("this", "a Buffer")
				}
				return TsCall(loop, TsNodeBufferGet(receiver, method), args...)
			}))
		}
		for _, class := range TsNativeClasses.Classes {
			class.NativePrototype.Descriptors = map[string]*TsDescriptor{}
			for _, key := range class.NativePrototype.Order {
				class.NativePrototype.Descriptors[key] = &TsDescriptor{Writable: true, Configurable: true}
			}
		}
		tagKey := TsPropertyKey(loop, TsWellKnownSymbol("toStringTag"))
		for _, name := range []string{"Stats", "BigIntStats", "StatFs", "BigIntStatFs", "Dirent"} {
			class := TsNativeClasses.Classes[name]
			class.NativePrototype.Set(tagKey, TsStringReference(TsStringUTF8(name)))
			class.NativePrototype.Descriptors[tagKey] = &TsDescriptor{Configurable: true}
		}
	})
	return TsNativeClasses.Classes[name]
}
func TsFSConstructStats(loop *TsLoop, args []TsValue) TsValue {
	out := TsNewObject()
	out.NativeClass = TsNativeClass(loop, "Stats")
	for index, name := range []string{"dev", "mode", "nlink", "uid", "gid", "rdev", "blksize", "ino", "size", "blocks", "atimeMs", "mtimeMs", "ctimeMs", "birthtimeMs"} {
		out.Set(name, TsArg(args, index))
	}
	return TsObjectValue(out)
}
func TsFSConstructBigIntStats(loop *TsLoop, args []TsValue) TsValue {
	out := TsNewObject()
	out.NativeClass = TsNativeClass(loop, "BigIntStats")
	for index, name := range []string{"dev", "mode", "nlink", "uid", "gid", "rdev", "blksize", "ino", "size", "blocks"} {
		out.Set(name, TsArg(args, index))
	}
	for index, name := range []string{"atime", "mtime", "ctime", "birthtime"} {
		value := TsArg(args, 10+index)
		if value.Kind != TsBigIntKind {
			panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "Cannot convert value to a BigInt"})})
		}
		nanoseconds := (*big.Int)(value.Ref)
		milliseconds := TsNumberValue(float64(nanoseconds.Int64()) / 1e6)
		out.Set(name+"Ms", milliseconds)
		out.Set(name+"Ns", TsBigIntValue(new(big.Int).Set(nanoseconds)))
	}
	return TsObjectValue(out)
}
func TsFSConstructStatFS(loop *TsLoop, args []TsValue, bigint bool) TsValue {
	class := "StatFs"
	if bigint {
		class = "BigIntStatFs"
	}
	out := TsNewObject()
	out.NativeClass = TsNativeClass(loop, class)
	for index, name := range []string{"type", "bsize", "frsize", "blocks", "bfree", "bavail", "files", "ffree"} {
		out.Set(name, TsArg(args, index))
	}
	return TsObjectValue(out)
}
func TsFSConstructDirent(loop *TsLoop, args []TsValue) TsValue {
	out := TsNewObject()
	out.NativeClass = TsNativeClass(loop, "Dirent")
	out.Set("name", TsArg(args, 0))
	out.Set("parentPath", TsArg(args, 2))
	out.Set("path", TsArg(args, 2))
	mode := os.ModeIrregular
	switch int(TsNumber(TsArg(args, 1))) {
	case 1:
		mode = 0
	case 2:
		mode = os.ModeDir
	case 3:
		mode = os.ModeSymlink
	case 4:
		mode = os.ModeNamedPipe
	case 5:
		mode = os.ModeSocket
	case 6:
		mode = os.ModeDevice | os.ModeCharDevice
	case 7:
		mode = os.ModeDevice
	}
	out.NativeMode = mode
	return TsObjectValue(out)
}

