func TsArrayBufferRegister(buffer *TsArrayBuffer, view *TsTypedArray) {
	if buffer.Detached {
		TsArrayTypeFailure("Cannot create a view of a detached ArrayBuffer")
	}
	if len(buffer.Views) >= 64 && len(buffer.Views)%64 == 0 {
		live := buffer.Views[:0]
		for _, reference := range buffer.Views {
			if reference.Value() != nil {
				live = append(live, reference)
			}
		}
		buffer.Views = live
	}
	buffer.Views = append(buffer.Views, weak.Make(view))
}
func TsArrayBufferTransfer(buffer *TsArrayBuffer, length int) *TsArrayBuffer {
	if buffer.Detached {
		TsArrayTypeFailure("Cannot transfer a detached ArrayBuffer")
	}
	data := buffer.Data
	if length != len(data) {
		resized := make([]byte, length)
		copy(resized, data)
		data = resized
	}
	output := &TsArrayBuffer{Data: data, MaxByteLength: buffer.MaxByteLength, Resizable: buffer.Resizable}
	for _, reference := range buffer.Views {
		var view *TsTypedArray
		view = reference.Value()
		if view == nil {
			continue
		}
		view.Length = 0
		view.Offset = 0
		view.Storage = nil
		view.RuntimeFieldRead = func(i int) float64 { TsArrayTypeFailure("Cannot read a detached TypedArray"); return 0 }
		view.RuntimeFieldWrite = func(i int, n float64) { TsArrayTypeFailure("Cannot write a detached TypedArray") }
		view.View = func(start, end int) *TsTypedArray {
			TsArrayTypeFailure("Cannot slice a detached TypedArray")
			return nil
		}
	}
	buffer.Views = nil
	buffer.Data = nil
	buffer.Detached = true
	return output
}
func TsBYOBTransfer(loop *TsLoop, value TsValue) TsValue {
	if value.Kind != TsTypedArrayKind {
		TsFSInvalid("view", "a TypedArray")
	}
	array := (*TsTypedArray)(value.Ref)
	if array.Buffer.Detached || array.Length == 0 {
		panic(TsThrown{TsFSException("TypeError", "ERR_INVALID_STATE", "BYOB view is empty or detached")})
	}
	offset, length, name, bufferMarker := array.Offset, array.Length, array.Name, array.NodeBuffer
	buffer := TsArrayBufferTransfer(array.Buffer, len(array.Buffer.Data))
	output := TsTypedArrayBufferExtended(loop, name, []TsValue{TsArrayBufferValue(buffer), TsNumberValue(float64(offset)), TsNumberValue(float64(length))})
	(*TsTypedArray)(output.Ref).NodeBuffer = bufferMarker
	return output
}
func TsByteView(data []byte) TsValue {
	value := TsNodeBuffer(data)
	(*TsTypedArray)(value.Ref).NodeBuffer = false
	return value
}

// tsLosslessNumericConversion reports whether every value of source is
// exactly representable in target. This is a type guarantee, not a value check.
func TsLosslessNumericConversion(target, source string) bool {
	if target == "float64" {
		target = "number"
	}
	if source == "float64" {
		source = "number"
	}
	width := func(kind string) int {
		switch kind {
		case "int8", "uint8":
			return 8
		case "int16", "uint16":
			return 16
		case "int32", "uint32":
			return 32
		case "int64", "uint64":
			return 64
		case "int", "uint":
			return strconv.IntSize
		}
		return 0
	}
	sourceBits, targetBits := width(source), width(target)
	if target == source {
		return sourceBits != 0 || target == "number" || target == "float32"
	}
	if source == "float32" && target == "number" {
		return true
	}
	if sourceBits == 0 {
		return false
	}
	if target == "number" || target == "float32" {
		precision := 53
		if target == "float32" {
			precision = 24
		}
		return sourceBits <= precision
	}
	if targetBits == 0 {
		return false
	}
	sourceUnsigned, targetUnsigned := strings.HasPrefix(source, "uint"), strings.HasPrefix(target, "uint")
	if sourceUnsigned == targetUnsigned {
		return targetBits >= sourceBits
	}
	return sourceUnsigned && !targetUnsigned && targetBits > sourceBits
}

func TsValueTypeName(value TsValue) string {
	switch value.Kind {
	case TsBigIntKind:
		return "bigint"
	case TsNumberKind:
		return "number"
	case TsFloat32Kind:
		return "float32"
	case TsIntKind:
		return "int"
	case TsInt8Kind:
		return "int8"
	case TsInt16Kind:
		return "int16"
	case TsInt32Kind:
		return "int32"
	case TsInt64Kind:
		return "int64"
	case TsUintKind:
		return "uint"
	case TsUint8Kind:
		return "uint8"
	case TsUint16Kind:
		return "uint16"
	case TsUint32Kind:
		return "uint32"
	case TsUint64Kind:
		return "uint64"
	case TsStringKind:
		return "string"
	case TsBooleanKind:
		return "boolean"
	case TsNullKind:
		return "null"
	case TsUndefinedKind:
		return "undefined"
	}
	return "object"
}
func TsConversionTypeFailure(target, source string) {
	panic(TsThrown{TsErrorValue(&TsRuntimeError{Name: "TypeError", Message: "Cannot implicitly convert " + source + " to " + target + " with coerceAny disabled; use ." + target + "()"})})
}
func TsParseNumberString(value *TsString) float64 {
	text := strings.TrimSpace(value.String())
	if text == "" {
		TsNumericRangeFailure("number: empty numeric text")
	}
	n := TsStringNumber(value)
	if math.IsNaN(n) && text != "NaN" {
		TsNumericRangeFailure("number: invalid numeric text")
	}
	return n
}
func TsParseIntegerText(value *TsString, kind string) *big.Int {
	text := strings.TrimSpace(value.String())
	TsParseNumberString(value)
	integer := new(big.Int)
	if _, ok := integer.SetString(text, 10); !ok {
		ratio, ok := new(big.Rat).SetString(text)
		if !ok || !ratio.IsInt() {
			TsNumericRangeFailure(kind)
		}
		integer.Set(ratio.Num())
	}
	return integer
}
func TsParseSignedInteger(value *TsString, kind string, bits int) int64 {
	text := strings.TrimSpace(value.String())
	n, err := strconv.ParseInt(text, 10, bits)
	if err == nil {
		return n
	}
	integer := TsParseIntegerText(value, kind)
	if !integer.IsInt64() {
		TsNumericRangeFailure(kind)
	}
	n = integer.Int64()
	if bits < 64 && (n < -(int64(1)<<(bits-1)) || n > (int64(1)<<(bits-1))-1) {
		TsNumericRangeFailure(kind)
	}
	return n
}
func TsParseUnsignedInteger(value *TsString, kind string, bits int) uint64 {
	text := strings.TrimSpace(value.String())
	n, err := strconv.ParseUint(text, 10, bits)
	if err == nil {
		return n
	}
	integer := TsParseIntegerText(value, kind)
	if integer.Sign() < 0 || integer.BitLen() > bits {
		TsNumericRangeFailure(kind)
	}
	return integer.Uint64()
}

