		out := &TsArray{}
		mapper := TsArg(args, 1)
		if !TsIsUndefined(mapper) && mapper.Kind != TsFunctionKind {
			panic("Array.from mapper must be callable")
		}
		it := TsArrayLikeIterator(loop, source)
		for it.Next(loop) {
			item := it.RuntimeFieldValue
			if mapper.Kind == TsFunctionKind {
				item = TsCall(loop, mapper, item, TsNumberValue(float64(len(out.Values))))
			}
			out.Values = append(out.Values, item)
		}
